mapper.insert:
/* CastFcltWtngRsltMapper.insertFcltWtngRsltList */ INSERT ALL
INTO PMOWN.TN_PM_SMLT_FCLT_WTNG_RSLT ( SMLT_ID, SMLT_MDL_SN, TMNL_ID, FCLT_TYPE_CD, FCLT_UNIT_CD, SEC_BGNG_DT, END_WTNG_PSG_CNT, PRCS_PSG_CNT, WTNG_PSEC_SUM, WTNG_VLD_PSG_CNT, PRCS_PSEC_SUM, PRCS_VLD_PSG_CNT, WTNG_PSG_CNT_SUM, WTNG_NOCS, MAX_WTNG_PSG_CNT, END_OPER_CNTOM, PRCS_CPCT, PRCS_VLD_OPER_CNTOM_SUM, OBSRVN_YN, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( #{item.smltId}, #{item.smltMdlSn}, #{item.tmnlId}, #{item.fcltTypeCd}, #{item.fcltUnitCd}, #{item.secBgngDt, jdbcType=TIMESTAMP}, #{item.endWtngPsgCnt, jdbcType=NUMERIC}, #{item.prcsPsgCnt}, #{item.wtngPsecSum, jdbcType=NUMERIC}, #{item.wtngVldPsgCnt}, #{item.prcsPsecSum, jdbcType=NUMERIC}, #{item.prcsVldPsgCnt}, #{item.wtngPsgCntSum}, #{item.wtngNocs}, #{item.maxWtngPsgCnt, jdbcType=NUMERIC}, #{item.endOperCntom, jdbcType=NUMERIC}, #{item.prcsCpct, jdbcType=NUMERIC}, #{item.prcsVldOperCntomSum, jdbcType=NUMERIC}, #{item.obsrvnYn}, 'CAST', #{loginIpAddr}, CURRENT_TIMESTAMP )
SELECT 1 FROM DUAL

mapper.select:
/* CastFcltWtngRsltMapper.retrieveFcltWtngRsltList */
SELECT
    A.SMLT_ID, A.SMLT_MDL_SN, A.TMNL_ID, A.FCLT_TYPE_CD, A.FCLT_UNIT_CD,
    A.SEC_BGNG_DT, A.END_WTNG_PSG_CNT, A.PRCS_PSG_CNT,
    A.WTNG_PSEC_SUM, A.WTNG_VLD_PSG_CNT, A.PRCS_PSEC_SUM, A.PRCS_VLD_PSG_CNT,
    A.WTNG_PSG_CNT_SUM, A.WTNG_NOCS, A.MAX_WTNG_PSG_CNT,
    A.END_OPER_CNTOM, A.PRCS_CPCT, A.PRCS_VLD_OPER_CNTOM_SUM, A.OBSRVN_YN
FROM PMOWN.TN_PM_SMLT_FCLT_WTNG_RSLT A
WHERE A.SMLT_ID = #{smltId}
AND A.SMLT_MDL_SN = #{smltMdlSn}
AND A.TMNL_ID = #{tmnlId}
AND A.FCLT_TYPE_CD = #{fcltTypeCd}
ORDER BY A.FCLT_UNIT_CD, A.SEC_BGNG_DT

/* CastFcltWtngRsltMapper.retrieveFcltWtngSrcList */
SELECT
    T.UNIT_CD,
    MIN(T.SMLT_ACTL_DT) AS MIN_ACTL_DT
FROM (
    SELECT
        A.SMLT_ACTL_DT,


        TRIM(SUBSTR(B.PSG_FCLT_CD, -3, 1)) AS UNIT_CD


        TRIM(SUBSTR(B.PSG_FCLT_CD, 5, 1)) AS UNIT_CD


    FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
        INNER JOIN PMOWN.TN_PM_SMLT_PSG_FCLT B
        ON A.PSG_FCLT_CD = B.PSG_FCLT_CD
    WHERE A.SMLT_ID = #{smltId}
    AND A.SMLT_MDL_SN = #{smltMdlSn}
    AND B.TMNL_ID = #{tmnlId}
    AND B.USE_YN = 'Y'
    AND B.UP_PSG_FCLT_CD IN (#{item})

    AND A.SMLT_ACTL_DT >= #{bgnDt}
    AND A.SMLT_ACTL_DT < #{endDt}

) T
GROUP BY T.UNIT_CD
ORDER BY T.UNIT_CD

/* CastFcltWtngRsltMapper.retrieveSrcExcnDtCnt */
SELECT COUNT(DISTINCT A.SMLT_EXCN_DT)
FROM PMOWN.TN_PM_SMLT_RSLT_DTL A
WHERE A.SMLT_ID = #{smltId}
AND A.SMLT_MDL_SN = #{smltMdlSn}
